idx = value['idx'] if value['idx'] is not None else 0
cfg = value['cfg']
tabs = []

for i in range(len(cfg)):
    item = cfg[i]

    tabs.append({
        "viewPath": "widgets(templates)/TabButton",

        "viewParams": {
            "tabText": item['tabText'],
            "toolTipText": item['toolTipText'],
            "tabSelected": (i == idx)
        },

        "runWhileHidden": False
    })

return tabs
